import re
from pathlib import Path
root=Path('flutter/src/main/ets')
files=list(root.rglob('*.ets'))
by={p.resolve():p for p in files}
edges={p.resolve():[] for p in files}
for p in files:
 s=p.read_text()
 for m in re.finditer(r'\\b(?:import|export)\\s+(?:[\\s\\S]*?\\s+from\\s+)?[\\'\\\"](["'^'"\\'\\\"]+)[\\'\\\"]',s):
  spec=m.group(1)
  if not spec.startswith('.'):
   continue
  q=(p.parent/spec)
  candidates=[q, q.with_suffix('.ets'), q/'index.ets']
  target=next((x.resolve() for x in candidates if x.resolve() in by),None)
  if target: edges[p.resolve()].append((target,spec,m.group(0).splitlines()[0].strip()))
# Tarjan SCC
idx=0; stack=[]; on=set(); inds={}; low={}; comps=[]
def visit(v):
 global idx
 inds[v]=low[v]=idx; idx+=1; stack.append(v); on.add(v)
 for w,_,_ in edges[v]:
  if w not in inds: visit(w); low[v]=min(low[v],low[w])
  elif w in on: low[v]=min(low[v],inds[w])
 if low[v]==inds[v]:
  c=[]
  while True:
   w=stack.pop(); on.remove(w); c.append(w)
   if w==v: break
  if len(c)>1 or any(a==v for a,_,_ in edges[v]): comps.append(c)
for v in edges:
 if v not in inds: visit(v)
for i,c in enumerate(sorted(comps,key=lambda x:(-len(x),str(x)))):
 print(f'SCC {i+1} size={len(c)}')
 cs=set(c)
 for p in sorted(c):
  print(' ',p.relative_to(Path.cwd()), 'imports:', ', '.join(f'{t.relative_to(Path.cwd())}' for t,s,_ in edges[p] if t in cs))
